import { shopifyCartAdd } from "@utils/api.js";

if (!customElements.get('v5-product-row-multi')) {
  customElements.define('v5-product-row-multi', class V5productRowMulti extends HTMLElement {
    constructor() {
      super()

      this.sid = this.getAttribute("section-id");
      // PC端、MB端，是否使用 swiper 布局
      this.pcIsSwiper = this.getAttribute('data-pc-is-swiper') === 'swiper'
      this.mbIsSwiper = this.getAttribute('data-mb-is-swiper') === 'true'

      // 使用 matchMedia 替代 ResizeObserver，性能更优
      this.mediaQuery = window.matchMedia('(min-width: 1024px)');

      this.timer = null
    }
    connectedCallback() {
      this.countdownDOM = this.querySelector('[data-count-down]')
      if (this.countdownDOM) {
        // 初始化 倒计时
        this.initCountdown()
      }

      // 初始化 swiper
      this.initSwiper()

      // 初始化 捆绑产品
      this.initBundleProduct()

      // 初始化 view more 按钮点击事件
      this.initViewMoreEvent()

      // 初始化 复制code 事件 
      this.initCodeCopyEvent()

      // 初始化 加购 事件
      this.initAddToCartEvent()

      // 初始化 订阅 事件
      this.initSunscribeEvent()
    }
    disconnectedCallback() {
      this.timer && clearTimeout(this.timer)
      // 移除监听事件
      this.mediaQuery && this.mediaQuery.removeEventListener('change', handleViewChange);
      this.swiper && this.swiper.destroy(true, true);
      this.resizeObserver && this.resizeObserver.disconnect();
    }
    // 初始化 倒计时
    initCountdown() {
      this.endsInText = this.countdownDOM.getAttribute('data-ends-in-text')
      this.countdownLabelText = this.countdownDOM.getAttribute('data-countdown-label-text').split(',')

      const shopifyTime = this.countdownDOM.getAttribute('data-shopify-time')
      const endTime = this.countdownDOM.getAttribute('data-end-time')

      const currentTime = new Date(shopifyTime).getTime();
      if (endTime) {
        const countdownEndTime = new Date(endTime || 0).getTime();

        // 开始倒计时
        clearTimeout(this.timer);
        this.tick(currentTime, countdownEndTime);
      }
    }
    // 倒计时 span
    renderCountdownSpan(days, hours, minutes, seconds) {
      const style = 'flex flex-col items-center justify-center gap-y-1 lg:gap-y-[0.1875rem] w-[3.25rem] h-[3.25rem] lg:w-16 lg:h-16 text-white bg-[var(--main-color)]'

      return `
        <span class="${style}">
          <span class="font-semibold text-[1.25rem] lg:text-[1.75rem] leading-none">${days || ''}</span>
          <span class="font-semobild text-[0.75rem] lg:text-[1rem] leading-none">${this.countdownLabelText[0]?.trim() || ''}</span>
        </span>
        <span class="flex items-center justify-center w-7 font-semibold text-2xl text-[var(--main-color)] -mt-0.5">:</span>
        <span class="${style}">
          <span class="font-semibold text-[1.25rem] lg:text-[1.75rem] leading-none">${hours || ''}</span>
          <span class="font-semobild text-[0.75rem] lg:text-[1rem] leading-none">${this.countdownLabelText[1]?.trim() || ''}</span>
        </span>
        <span class="flex items-center justify-center w-7 font-semibold text-2xl text-[var(--main-color)] -mt-0.5">:</span>
        <span class="${style}">
          <span class="font-semibold text-[1.25rem] lg:text-[1.75rem] leading-none">${minutes || ''}</span>
          <span class="font-semobild text-[0.75rem] lg:text-[1rem] leading-none">${this.countdownLabelText[2]?.trim() || ''}</span>
        </span>
        <span class="flex items-center justify-center w-7 font-semibold text-2xl text-[var(--main-color)] -mt-0.5">:</span>
        <span class="${style}">
          <span class="font-semibold text-[1.25rem] lg:text-[1.75rem] leading-none">${seconds || ''}</span>
          <span class="font-semobild text-[0.75rem] lg:text-[1rem] leading-none">${this.countdownLabelText[3]?.trim() || ''}</span>
        </span>
      `
    }
    // 倒计时
    tick(current, target) {
      const leftTime = (target - current) / 1000
      let days, hours, minutes, seconds

      // 倒计时结束
      if (leftTime <= 0) {
        this.timer && clearTimeout(this.timer)

        // 隐藏 DOM
        this.style.display = 'none'
      } else {
        days = String(parseInt(leftTime / 60 / 60 / 24)).padStart(2, '0')
        hours = String(parseInt(leftTime / 60 / 60 % 24)).padStart(2, '0')
        minutes = String(parseInt(leftTime / 60 % 60)).padStart(2, '0')
        seconds = String(parseInt(leftTime % 60)).padStart(2, '0')

        if (this.countdownDOM) {
          this.countdownDOM.innerHTML = this.renderCountdownSpan(days, hours, minutes, seconds)
        }

        this.timer = setTimeout(() => this.tick(current + 1000, target), 1000)
      }
    }
    // 初始化 swiper
    initSwiper() {
      const swiperContainer = this.querySelector('.swiper');
      if (!swiperContainer) return;
      
      const handleViewChange = (e) => {
        const isPC = e.matches;

        if (this.swiper) {
          this.swiper.destroy(true, true);
          this.swiper = null;
        }

        if (isPC) {
          // 屏幕 >= 1024px
          if (this.pcIsSwiper) {
            this.createSwiper(swiperContainer, 'pc');
          }
        } else {
          // 屏幕 < 1024px
          if (this.mbIsSwiper) {
            this.createSwiper(swiperContainer, 'mb');
          }
        }
      };

      // 初始化检查 & 监听
      this.mediaQuery.addEventListener('change', handleViewChange);
      handleViewChange(this.mediaQuery);
    }
    // 实例化 swiper
    createSwiper(container, type = 'mb') {
      const isPC = type === 'pc';
      const options = {
        slidesPerView: 'auto',
        autoHeight: false,
        centeredSlides: false,
        loop: false,
        watchSlidesProgress: true,
        watchSlidesVisibility: true,
        observer: true, // 开启动态检查器，监测swiper和slide
        observeParents: true, // 监测Swiper 的祖/父元素
        observeSlideChildren: true,
        lazy: {
          loadPrevNext: true,
          loadPrevNextAmount: 1
        },
        allowTouchMove: true,
      };

      if (isPC) {
        const nextEl = this.querySelector('.swiper-button-next');
        const prevEl = this.querySelector('.swiper-button-prev');
        if (nextEl && prevEl) {
          options.navigation = {
            nextEl,
            prevEl,
          };
        }
      }

      this.swiper = new Swiper(container, options);
    }
    // 初始化 view more 按钮点击事件
    initViewMoreEvent() {
      this.querySelectorAll('[data-view-more-btn]').forEach(item => {
        item.addEventListener('click', (e) => {
          e.preventDefault()

          // 显示更多产品
          this.querySelectorAll('[data-card-item]').forEach(card => {
            card.classList.remove('!hidden', 'lg:!hidden')
            card.classList.add('!flex', 'lg:!flex')
          })

          // 隐藏按钮
          item.style.display = 'none'

          // 更新父组件高度
          const height = this.measureParentHeight()
          const targetRoot = this.closest('.tab-content-wrap');
          if (height > 0 && targetRoot && targetRoot.contains(this)) {
            document.dispatchEvent(new CustomEvent('tabChildUpdateHeight', {
              detail: {
                height,
                parentDOM: targetRoot
              }
            }))
          }
        })
      })
    }
    // 测量稳定高度
    measureParentHeight() {
      const rectH = this.getBoundingClientRect().height || 0
      const offsetH = this.offsetHeight || 0
      const scrollH = this.scrollHeight || 0
      return Math.max(rectH, offsetH, scrollH)
    }
    // 初始化 复制code 事件 
    initCodeCopyEvent() {
      // 注册 click 事件
      this.querySelectorAll('[data-code-wrap]').forEach(item => {
        item.addEventListener('click', (e) => {
          const { code, copySuccess, copyCheckout, skuId } = e.currentTarget.dataset

          // 复制
          copyString(code, () => {
            // 提示 copy 成功
            pushSuccessMessage(copySuccess)

            if (copyCheckout === 'true') {
              // 设置 cookie
              let d = new Date()
              d.setTime(d.getTime() + (7 * 24 * 60 * 60 * 1000)) // 7天
              document.cookie = `discount_code=${code};expires=${d.toGMTString()};path=/`

              setTimeout(async () => {
                const items = [{
                  id: skuId,
                  quantity: 1,
                  properties: {}
                }]

                // 创建购物车并返回 checkout url 并跳转，方法内部已做容错处理，一定会返回 checkout url
                const checkoutUrl = await createCartAndCheckout(items)
                window.location.href = checkoutUrl
              }, 500)
            }
          })
        })
      })
    }
    // 初始化加购事件
    initAddToCartEvent() {
      this.querySelectorAll('[data-add-to-cart-btn]').forEach(item => {
        item.addEventListener('click', async (e) => {
          const target = e.currentTarget
          // loading
          target.classList.add('loading')

          // 主产品 skuId
          const skuId = target.getAttribute('data-sku-id');

          const items = [
            {
              id: Number(skuId),
              quantity: 1,
              properties: {}
            }
          ]

          // 捆绑产品 skuId
          const bundleDOM = target.closest('[data-card-item]').querySelector('[data-bundle-product]')
          const quantityInput = bundleDOM?.querySelector('[data-quantity-input]')
          if (quantityInput) {
            const params = {
              id: Number(quantityInput.getAttribute('data-sku-id')),
              quantity: Number(quantityInput.value),
              properties: {}
            }

            // PC端
            if (this.mediaQuery.matches) {
              // PC端：检查是否有效
              if (!bundleDOM?.hasAttribute('data-pc-not-valid')) {
                items.push(params)
              }
            } else {
              // 移动端：检查是否有效
              if (!bundleDOM?.hasAttribute('data-mb-not-valid')) {
                items.push(params)
              }
            }
          }

          // 触发添加到购物车的事件
          const cart = document.querySelector('cart-notification') || document.querySelector('cart-drawer');
          try {
            const data = await shopifyCartAdd({ items, });
            if (cart) {
              cart.renderContents(data)
            } else {
              window.location.href = '/cart'
            }
          } catch (err) {
            console.error(err)
          } finally {
            // 移除loading
            target.classList.remove('loading')
          }
        })
      })
    }
    // 初始化 捆绑产品
    async initBundleProduct() {
      const bundleDOMs = this.querySelectorAll('[data-bundle-product]')
      if (!bundleDOMs.length) return

      try {
        const skuIdsSet = new Set()
        bundleDOMs.forEach(DOM => {
          const skuId = Number(DOM.getAttribute('data-sku-id'))
          if (skuId && !isNaN(skuId)) skuIdsSet.add(skuId)
        })
        const skuIds = Array.from(skuIdsSet)
        if (skuIds.length === 0) return

        // 获取并显示捆绑产品信息
        const data = await this.fetchBundleData(skuIds)
        if (data && data.length > 0) {
          bundleDOMs.forEach(DOM => {
            const skuId = Number(DOM.getAttribute('data-sku-id'))
            const matchedItem = data.find(d => Number(d.originSkuId) === skuId)
            if (matchedItem && matchedItem.bundleGoodsList?.length > 0) {
              const item = matchedItem.bundleGoodsList[0]
              DOM.innerHTML = this.renderBundleProduct(item)

              // 初始化 quantity-input 交互事件
              this.initQuantityEvent(DOM)
            } else {
              // 清空DOM
              DOM.innerHTML = ''

              // PC端，以及MB端轮播时，根据配置显示占位
              const showPriceUp = DOM.getAttribute('data-show-price-up') === 'true'
              if (showPriceUp) {
                DOM.classList.add('lg:invisible')
                if (this.mbIsSwiper) {
                  DOM.classList.add('invisible')
                } else {
                  DOM.classList.add('hidden')
                }
              } else {
                DOM.classList.add('hidden', 'lg:hidden')
              }
            }
          })
        }
      } catch (error) {
        console.error(error)
      }
    }
    // 捆绑产品，实际的API请求方法
    async fetchBundleData(skuIds) {
      const response = await fetch(`${window.pageInfo.api}/osconsumerapi/v1/app-bundled-sale/infos`, {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'cr': window?.pageInfo?.cr || '',
          'lang': window?.pageInfo?.lang || 'en',
        },
        body: JSON.stringify({
          skuIds: skuIds,
          shopifyShopId: window.pageInfo.shopId,
        }),
      })

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`)
      }

      const res = await response.json()
      return res.code === 200 ? res.data || [] : []
    }
    // 格式化 捆绑产品 价格显示
    formatPrice(price) {
      if (typeof window.formatMoney === 'function' && window?.pageInfo?.currency?.money_format) {
        const formattedPrice = window.formatMoney(price * 100, window.pageInfo.currency.money_format)
        // 如果价格为0，保持显示$0，否则移除.00
        return price === 0 ? formattedPrice.replace('.00', '') || '$0' : formattedPrice.replace('.00', '')
      }
      // 如果价格为0，显示$0，否则移除.00后缀
      const formatted = `$${price.toFixed(2)}`
      return price === 0 ? '$0' : formatted.replace('.00', '')
    }
    // 渲染 捆绑产品
    renderBundleProduct(item) {
      const mbIsSwiper = this.mbIsSwiper
      return `
        <img class="${mbIsSwiper ? 'w-10 h-10' : 'w-[3.75rem] h-[3.75rem]'} lg:w-[3.75rem] lg:h-[3.75rem] object-contain flex-shrink-0" src="${item.image}" width="75" height="75" alt="${item.title || 'Bundle Product'}" loading="lazy">
        <div class="flex-1 flex flex-col gap-y-3">
          <h2 class="font-normal text-[#242F20] ${mbIsSwiper ? 'text-[0.75rem]' : 'text-[0.875rem]'} line-clamp-2 leading-[1.2]" title="${item.title.replace(/^Jackery\s*/i, '').trim()}">${item.title.replace(/^Jackery\s*/i, '').trim()}</h2>
          <div class="flex ${mbIsSwiper ? 'flex-col items-start gap-y-3 lg:flex-row lg:items-center lg:justify-between' : 'items-center justify-between'}">
            <p class="flex items-center gap-x-1">
              ${item.price >= 0
                ? `<span class="text-[#9D1D22] ${mbIsSwiper ? 'text-xs' : 'text-sm'}">${this.formatPrice(item.price)}</span>`
                : ''
              }
              ${item.originPrice > item.price
                ? `<span class="text-black/65 ${mbIsSwiper ? 'text-xs' : 'text-sm'} line-through">${this.formatPrice(item.originPrice)}</span>`
                : ''
              }
            </p>
            <div class="flex border-solid border-[#94948F] border-[1px]">
              <button
                class="appearance-none bg-transparent flex items-center justify-center w-7 h-7 disabled:opacity-40 disabled:cursor-not-allowed"
                disabled
                data-button-minus
              >
                <svg class="icon icon-minus text-[#94948F] w-3.5 h-3.5" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" role="presentation" fill="none" viewBox="0 0 10 2">
                  <path fill-rule="evenodd" clip-rule="evenodd" d="M.5 1C.5.7.7.5 1 .5h8a.5.5 0 110 1H1A.5.5 0 01.5 1z" fill="currentColor">
                </svg>
              </button>
              <input
                class="text-[#94948F] flex items-center justify-center font-semibold text-center border-0 w-8 h-7 lg:w-9 text-base"
                type="number"
                value="1"
                data-max="${item.stock}"
                data-sku-id="${item.skuId}"
                readonly
                data-quantity-input
              />
              <button
                class="appearance-none bg-transparent flex items-center justify-center w-7 h-7 disabled:opacity-40 disabled:cursor-not-allowed"
                data-button-plus
                ${item.stock <= 1 ? 'disabled' : ''}
              >
                <svg class="icon icon-plus text-[#94948F] w-3.5 h-3.5" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" role="presentation" fill="none" viewBox="0 0 10 10">
                  <path fill-rule="evenodd" clip-rule="evenodd" d="M1 4.51a.5.5 0 000 1h3.5l.01 3.5a.5.5 0 001-.01V5.5l3.5-.01a.5.5 0 00-.01-1H5.5L5.49.99a.5.5 0 00-1 .01v3.5l-3.5.01H1z" fill="currentColor">
                </svg>
              </button>
            </div>
          </div>
        </div>
      `
    }
    // 初始化 quantity-input 交互事件
    initQuantityEvent(DOM) {
      const minusBtns = DOM.querySelectorAll('[data-button-minus]')
      const quantityInputs = DOM.querySelectorAll('[data-quantity-input]')
      const plusBtns = DOM.querySelectorAll('[data-button-plus]')

      function handleMinus(e) {
        e.preventDefault()

        quantityInputs.forEach(it => {
          plusBtns.forEach(m => m.removeAttribute('disabled'))
          it.value = it.value * 1 > 1 ? it.value * 1 - 1 : 1

          if (it.value == 1) {
            e.currentTarget.setAttribute('disabled', 'disabled')
          }
        })
      }

      function handlePlus(e) {
        e.preventDefault()

        quantityInputs.forEach(it => {
          minusBtns.forEach(m => m.removeAttribute('disabled'))
          it.value = it.value * 1 < Number(it.dataset.max) ? it.value * 1 + 1 : Number(it.dataset.max)

          if (it.value == Number(it.dataset.max)) {
            e.currentTarget.setAttribute('disabled', 'disabled')
          }
        })
      }

      minusBtns.forEach(it => {
        it.removeEventListener('click', handleMinus)
        // 避免重复注册 click 事件
        if (!it.dataset.hasEvent) {
          it.addEventListener('click', handleMinus)
          it.dataset.hasEvent = true
        }
      })

      plusBtns.forEach(it => {
        it.removeEventListener('click', handlePlus)
        // 避免重复注册 click 事件
        if (!it.dataset.hasEvent) {
          it.addEventListener('click', handlePlus)
          it.dataset.hasEvent = true
        }
      })
    }
    // 初始化 订阅事件
    initSunscribeEvent() {
      const sunscribeBtns = this.querySelectorAll('[data-subsciber-btn]')
      if (!sunscribeBtns.length) return

      sunscribeBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
          const dialog = document.querySelector(`jds-dialog[id="${this.sid}"]`)
          dialog?.setAttribute?.('open', true)

          // 清空错误提示
          const fields = dialog.querySelectorAll('jky-form .form-item.required')
          fields.forEach(field => dialog.querySelector('jky-form').handleRemoveError(field))

          dialog.querySelector('jky-form').setAttribute('data-sku-id', e.currentTarget.dataset.skuId)
          dialog.querySelector('jky-phoneselect')?.updateInputPaddingLeft?.()
        })

        // 更新订阅按钮状态
        this.checkSubscribeCache(btn, btn.dataset.skuId)
      })

      document.addEventListener('jkyFormSubmitEvent', (e) => {
        const { id } = e.detail
        if (id === this.sid) {
          const dialog = document.querySelector(`jds-dialog[id="${this.sid}"]`)
          const skuId = dialog.querySelector('jky-form').getAttribute('data-sku-id')
          const btn = this.querySelector(`[data-subsciber-btn][data-sku-id="${skuId}"]`)
          this.handleSubscribeCache(btn, skuId)

          dialog?.removeAttribute?.('open')
        }
      })
    }
    // 处理订阅缓存
    handleSubscribeCache(btn, skuId) {
      const preData = localStorage.getItem('Product-Component-Subscribed');
      let items = preData ? JSON.parse(preData) : [];

      const now = new Date();
      items.push({
        value: skuId,
        expiry: now.getTime() + 86400000
      });
      localStorage.setItem('Product-Component-Subscribed', JSON.stringify(items));
      // 更新 按钮状态为已订阅
      btn.setAttribute('disabled', 'disabled')
      // 图标 更新为实心
      const heartUse = btn.querySelector('#heart-use');
      heartUse.setAttribute('href', '#icon-heart-fill');
    }
    // 检查订阅缓存
    checkSubscribeCache(btn, skuId) {
      const _cache = localStorage.getItem('Product-Component-Subscribed');
      if (!_cache) return false

      let _cache_data = JSON.parse(_cache);
      const now = new Date();
      _cache_data.forEach(item => {
        if (item.value === skuId) {
          // 图标
          const heartUse = btn.querySelector('#heart-use');

          if (now.getTime() < item.expiry) {
            // 更新 按钮状态为已订阅
            btn.setAttribute('disabled', 'disabled')
            // 更新 图标 为实心
            heartUse.setAttribute('href', '#icon-heart-fill');
          } else {
            // 更新 按钮状态为可订阅
            btn.removeAttribute('disabled')
            // 更新 图标 为空心
            heartUse.setAttribute('href', '#icon-heart-line');

            // 删除缓存
            _cache_data.splice(_cache_data.indexOf(item), 1);
            localStorage.setItem('Product-Component-Subscribed', JSON.stringify(_cache_data));
          }
        }
      })

      if (_cache_data.length === 0) {
        localStorage.removeItem('Product-Component-Subscribed');
      }
    }
  })
}
